const file = items[0].json;

// Clean the filename into a readable title
const filename = file.name || 'Untitled Video';
const rawTitle = filename.substring(0, filename.lastIndexOf('.')) || filename;
const videoTitle = rawTitle
  .replace(/_/g, ' ')
  .replace(/-/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Preserve any description set on the Drive file
const videoDescription = file.description || '';

return [{
  json: {
    ...file,
    videoTitle,
    videoDescription
  }
}];

