const rawOutput = items[0].json.output;

// Strip any markdown code fences if Gemini added them
let clean = rawOutput
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// Find the first { and last } to extract the JSON object safely
const start = clean.indexOf('{');
const end = clean.lastIndexOf('}');
if (start === -1 || end === -1) {
  throw new Error('Gemini did not return valid JSON. Raw output: ' + rawOutput);
}
clean = clean.substring(start, end + 1);

const data = JSON.parse(clean);

// Handle tags as either array or comma-separated string
const rawTags = data.youtubeTags || [];
const tagsArray = Array.isArray(rawTags)
  ? rawTags
  : rawTags.split(',');

const tagsString = tagsArray
  .map(t => t.trim().substring(0, 30))
  .filter(t => t.length > 0)
  .slice(0, 20)
  .join(',');

return [{
  json: {
    ...items[0].json,
    youtubeTitle: (data.youtubeTitle || '').substring(0, 100),
    youtubeDescription: data.youtubeDescription || '',
    youtubeTags: tagsString,
    thumbnailPrompt: data.thumbnailPrompt || ''
  }
}];
